package app

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"time"

	"github.com/Antonio7098/ultraplan-go/internal/runcontrol"
	"github.com/Antonio7098/ultraplan-go/internal/sprint"
)

type durableOperationManager struct {
	repository runcontrol.Repository
	owner      runcontrol.Owner
	mu         sync.Mutex
	owned      map[string]*ownedDurableOperation
}

type ownedDurableOperation struct {
	fence        runcontrol.Fence
	cancel       context.CancelFunc
	stop         chan struct{}
	done         chan struct{}
	eventMu      sync.Mutex
	progressKey  string
	progressAt   time.Time
	omitted      uint64
	omittedFirst time.Time
	omittedLast  time.Time
}

// durableCLICommand is the synchronous CLI counterpart to the web/TUI
// acceptance boundary. It keeps the manager alive for the whole command and
// gives product code the cancellation-aware context owned by the durable run.
type durableCLICommand struct {
	manager  *durableOperationManager
	accepted AcceptedOperation
}

type durableOperationContextKey struct{}

type durableOperationOwnership struct {
	repository runcontrol.Repository
	fence      runcontrol.Fence
}

func beginDurableCLICommand(deps dependencies, request OperationRequest) (*durableCLICommand, error) {
	repository, _, err := runRepository(deps)
	if err != nil {
		return nil, err
	}
	manager := newDurableOperationManager(repository, deps.runControl.owner)
	accepted, err := manager.AcceptOperation(deps.ctx, Confirmation{Request: request}, "")
	if err != nil {
		return nil, classifiedCause(ExitRuntime, err, "run-control.accept")
	}
	return &durableCLICommand{manager: manager, accepted: accepted}, nil
}

func (c *durableCLICommand) Context() context.Context { return c.accepted.Context }

func (c *durableCLICommand) QAWriterToken() (sprint.QAWriterToken, func(sprint.QAWriterToken) error, error) {
	if c == nil {
		return sprint.QAWriterToken{}, nil, errors.New("durable QA ownership is unavailable")
	}
	return qaOwnershipFromContext(c.accepted.Context)
}

func (c *durableCLICommand) Finish(runErr error) error {
	state := OperationComplete
	if c.accepted.Context.Err() != nil {
		state = OperationCancelled
	} else if runErr != nil {
		state = OperationFailed
	}
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	if err := c.manager.FinishOperation(ctx, c.accepted.RunID, state, runErr); err != nil {
		return classifiedCause(ExitRuntime, err, "run-control.finish")
	}
	return nil
}

func finishDurableCLICommand(command *durableCLICommand, runErr error) error {
	if command == nil {
		return runErr
	}
	return errors.Join(runErr, command.Finish(runErr))
}

func newDurableOperationManager(repository runcontrol.Repository, owner runcontrol.Owner) *durableOperationManager {
	return &durableOperationManager{repository: repository, owner: owner, owned: make(map[string]*ownedDurableOperation)}
}

func (m *durableOperationManager) AcceptOperation(ctx context.Context, confirmation Confirmation, digest string) (AcceptedOperation, error) {
	req := confirmation.Request
	target := runcontrol.Target{
		Kind: "operation", Operation: string(req.Kind), Project: req.Project, Sprint: req.Sprint,
		Study: req.Study, Stage: req.Stage, Task: req.Task,
	}
	snapshot, err := m.repository.Accept(ctx, runcontrol.Acceptance{
		Target: target, ProductStatus: "prepared", OperationAlias: digest, ConfirmationDigest: digest,
	})
	if err != nil && digest != "" && errors.Is(err, runcontrol.ErrConflict) {
		existing, resolveErr := m.repository.ResolveOperationAlias(ctx, digest)
		if resolveErr != nil {
			return AcceptedOperation{}, errors.Join(err, resolveErr)
		}
		return AcceptedOperation{RunID: string(existing.RunID), Context: ctx, Existing: true, Lifecycle: string(existing.Lifecycle)}, nil
	}
	if err != nil {
		return AcceptedOperation{}, fmt.Errorf("persist confirmed operation acceptance: %w", err)
	}
	attempt, _, err := m.repository.Claim(ctx, runcontrol.Claim{RunID: snapshot.RunID, Owner: m.owner, Lease: runcontrol.OwnerLeaseDuration})
	if err != nil {
		return AcceptedOperation{}, fmt.Errorf("persist confirmed operation owner claim: %w", err)
	}
	fence := runcontrol.Fence{RunID: snapshot.RunID, AttemptID: attempt.ID, OwnerID: m.owner.ID, FencingGeneration: attempt.FencingGeneration}
	if _, _, err := appendRunEventWithRetry(ctx, m.repository, fence, runcontrol.EventDraft{
		Type: runcontrol.EventLifecycle, Lifecycle: runcontrol.LifecycleRunning,
		Payload: map[string]string{"lifecycle": string(runcontrol.LifecycleRunning)},
	}); err != nil {
		terminalCtx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
		_, _, _ = proposeRunTerminalWithRetry(terminalCtx, m.repository, fence, runcontrol.TerminalProposal{Outcome: runcontrol.TerminalPersistenceLost, Reason: "operation start persistence failed", ProposedBy: m.owner.ID})
		cancel()
		return AcceptedOperation{}, fmt.Errorf("persist confirmed operation start: %w", err)
	}
	operationCtx, cancel := context.WithCancel(runcontrol.WithParentRun(ctx, snapshot.RunID))
	operationCtx = context.WithValue(operationCtx, durableOperationContextKey{}, durableOperationOwnership{repository: m.repository, fence: fence})
	owned := &ownedDurableOperation{fence: fence, cancel: cancel, stop: make(chan struct{}), done: make(chan struct{})}
	m.mu.Lock()
	m.owned[string(snapshot.RunID)] = owned
	m.mu.Unlock()
	go m.controlOperation(operationCtx, owned)
	return AcceptedOperation{RunID: string(snapshot.RunID), Context: operationCtx, Lifecycle: string(runcontrol.LifecycleRunning)}, nil
}

func qaOwnershipFromContext(ctx context.Context) (sprint.QAWriterToken, func(sprint.QAWriterToken) error, error) {
	ownership, ok := ctx.Value(durableOperationContextKey{}).(durableOperationOwnership)
	if !ok || ownership.repository == nil {
		return sprint.QAWriterToken{}, nil, errors.New("durable QA ownership is missing from the operation context")
	}
	token := sprint.QAWriterToken{RunID: string(ownership.fence.RunID), OperationalAttemptID: string(ownership.fence.AttemptID), FencingGeneration: ownership.fence.FencingGeneration}
	fence := func(got sprint.QAWriterToken) error {
		if got != token {
			return runcontrol.ErrStaleFence
		}
		fenceCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), 30*time.Second)
		defer cancel()
		_, err := ownership.repository.Heartbeat(fenceCtx, ownership.fence, runControlLease)
		return err
	}
	return token, fence, nil
}

func (m *durableOperationManager) RecordOperationEvent(ctx context.Context, runID string, event OperationEvent) (bool, error) {
	m.mu.Lock()
	owned := m.owned[runID]
	m.mu.Unlock()
	if owned == nil {
		return false, runcontrol.ErrNotFound
	}
	owned.eventMu.Lock()
	defer owned.eventMu.Unlock()
	eventType := runcontrol.EventProgress
	if event.State == OperationFailed {
		eventType = runcontrol.EventWarning
	}
	key := string(eventType) + "\x00" + event.Stage + "\x00" + event.Task + "\x00" + event.PhaseState + "\x00" + event.SafeSummary + "\x00" + event.EventType + "\x00" + event.EventKind + "\x00" + event.Tool + "\x00" + event.Reason + "\x00" + event.Detail
	now := time.Now().UTC()
	elapsed := now.Sub(owned.progressAt)
	if eventType == runcontrol.EventProgress && key == owned.progressKey && elapsed >= 0 && elapsed < runcontrol.ProgressCoalesceWindow {
		if owned.omitted == 0 {
			owned.omittedFirst = now
		}
		owned.omitted++
		owned.omittedLast = now
		return false, nil
	}
	payload := map[string]string{
		"state": string(event.State), "type": event.EventType,
		"count": fmt.Sprintf("%d/%d", event.Completed, event.Total),
	}
	for key, value := range map[string]string{
		"phase_state": event.PhaseState, "summary": event.SafeSummary,
		"tool_call_id": event.ToolCallID, "tool_status": event.ToolStatus,
		"tool_arguments": event.ToolArguments, "tool_result": event.ToolResult, "tool_error": event.ToolError,
		"provider": event.Provider, "model": event.Model, "harness": event.Harness,
	} {
		if value != "" {
			payload[key] = value
		}
	}
	var omission *runcontrol.Omission
	if event.Message != "" {
		omission = &runcontrol.Omission{Reason: "presentation message omitted", Count: 1}
	}
	if owned.omitted > 0 {
		if omission == nil {
			omission = &runcontrol.Omission{Reason: "equivalent progress coalesced"}
		}
		omission.Count += owned.omitted
		omission.FirstAt, omission.LastAt = &owned.omittedFirst, &owned.omittedLast
		owned.omitted = 0
	}
	_, _, err := appendRunEventWithRetry(ctx, m.repository, owned.fence, runcontrol.EventDraft{
		Type: eventType, Scope: runcontrol.EventScopeOperation, Stage: event.Stage, Task: event.Task,
		Kind: event.EventKind, Tool: event.Tool, Action: event.Action, Reason: event.Reason,
		Detail: event.Detail, Payload: payload, Omission: omission,
	})
	if err != nil {
		owned.cancel()
		return false, err
	}
	if eventType == runcontrol.EventProgress {
		owned.progressKey, owned.progressAt = key, now
	}
	return true, nil
}

func (m *durableOperationManager) controlOperation(ctx context.Context, owned *ownedDurableOperation) {
	defer close(owned.done)
	ticker := time.NewTicker(runcontrol.OwnerTickInterval)
	defer ticker.Stop()
	lastHeartbeat, lastReconcile := time.Now(), time.Now()
	for {
		select {
		case <-ctx.Done():
			return
		case <-owned.stop:
			return
		case now := <-ticker.C:
			snapshot, err := m.repository.Snapshot(ctx, owned.fence.RunID)
			if err != nil {
				owned.cancel()
				return
			}
			if snapshot.Cancellation.State == runcontrol.CancellationRequested {
				if _, _, err := m.repository.AcknowledgeCancellation(ctx, owned.fence); err != nil {
					owned.cancel()
					return
				}
				owned.cancel()
				return
			}
			if now.Sub(lastHeartbeat) >= runcontrol.HeartbeatInterval {
				if _, err := m.repository.Heartbeat(ctx, owned.fence, runcontrol.OwnerLeaseDuration); err != nil {
					owned.cancel()
					return
				}
				lastHeartbeat = now
			}
			if now.Sub(lastReconcile) >= runcontrol.ReconciliationInterval {
				if _, err := m.repository.Reconcile(ctx, runcontrol.NativeProcessProbe{}, runcontrol.ReconcileOptions{}); err != nil {
					owned.cancel()
					return
				}
				lastReconcile = now
			}
		}
	}
}

func (m *durableOperationManager) FinishOperation(ctx context.Context, runID string, state OperationState, runErr error) error {
	m.mu.Lock()
	owned := m.owned[runID]
	delete(m.owned, runID)
	m.mu.Unlock()
	if owned == nil {
		return nil
	}
	owned.eventMu.Lock()
	if owned.omitted > 0 {
		_, _, appendErr := appendRunEventWithRetry(ctx, m.repository, owned.fence, runcontrol.EventDraft{Type: runcontrol.EventOmission, Omission: &runcontrol.Omission{Reason: "equivalent progress coalesced", Count: owned.omitted, FirstAt: &owned.omittedFirst, LastAt: &owned.omittedLast}})
		if appendErr != nil && runErr == nil {
			runErr = appendErr
		}
		owned.omitted = 0
	}
	owned.eventMu.Unlock()
	close(owned.stop)
	<-owned.done
	owned.cancel()
	outcome := runcontrol.TerminalSucceeded
	reason := "operation completed"
	switch {
	case errors.Is(runErr, context.DeadlineExceeded):
		outcome, reason = runcontrol.TerminalTimedOut, "operation deadline exceeded"
	case errors.Is(runErr, context.Canceled), state == OperationCancelled:
		outcome, reason = runcontrol.TerminalCancelled, "operation cancelled"
	case runErr != nil, state == OperationFailed:
		outcome, reason = runcontrol.TerminalFailed, "operation failed"
	case state == OperationPartial:
		outcome, reason = runcontrol.TerminalInterrupted, "operation interrupted"
	}
	_, _, err := proposeRunTerminalWithRetry(ctx, m.repository, owned.fence, runcontrol.TerminalProposal{Outcome: outcome, Reason: reason, ProposedBy: m.owner.ID})
	return err
}

package app

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"sort"
	"strings"
	"sync"
	"time"

	"github.com/Antonio7098/ultraplan-go/internal/platform/config"
	runtimepkg "github.com/Antonio7098/ultraplan-go/internal/platform/runtime"
	"github.com/Antonio7098/ultraplan-go/internal/runcontrol"
)

const runControlLease = runcontrol.OwnerLeaseDuration

// runControlState owns one repository handle per workspace for the lifetime of
// the process. dependencies is copied throughout command dispatch, so keeping
// this state behind a pointer prevents accidental duplicate connection pools.
type runControlState struct {
	mu       sync.Mutex
	repos    map[string]*runcontrol.SQLiteRepository
	loggers  map[string]*runcontrol.LocalFileLogger
	policies map[string]runcontrol.RetentionPolicy
	owner    runcontrol.Owner
	initErr  error
}

func newRunControlState() *runControlState {
	owner, err := currentRunOwner()
	return &runControlState{repos: make(map[string]*runcontrol.SQLiteRepository), loggers: make(map[string]*runcontrol.LocalFileLogger), policies: make(map[string]runcontrol.RetentionPolicy), owner: owner, initErr: err}
}

func (s *runControlState) repository(ctx context.Context, workspaceRoot string, policies ...runcontrol.RetentionPolicy) (*runcontrol.SQLiteRepository, error) {
	if s == nil {
		return nil, errors.New("run-control process state is unavailable")
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.initErr != nil {
		return nil, s.initErr
	}
	if repository := s.repos[workspaceRoot]; repository != nil {
		if len(policies) > 0 && s.policies[workspaceRoot] != policies[0] {
			return nil, errors.New("run-control retention policy changed during the process lifetime")
		}
		return repository, nil
	}
	var retention runcontrol.RetentionPolicy
	if len(policies) > 0 {
		retention = policies[0]
	}
	repository, err := runcontrol.OpenSQLite(ctx, workspaceRoot, runcontrol.SQLiteOptions{Retention: retention})
	if err != nil {
		return nil, err
	}
	logger, err := runcontrol.OpenLocalFileLogger(workspaceRoot)
	if err != nil {
		_ = repository.Close()
		return nil, fmt.Errorf("open run-control diagnostic log: %w", err)
	}
	repository.SetLogger(logger)
	if _, err := repository.Reconcile(ctx, runcontrol.NativeProcessProbe{}, runcontrol.ReconcileOptions{}); err != nil {
		_ = repository.Close()
		_ = logger.Close()
		return nil, fmt.Errorf("startup run reconciliation failed: %w", err)
	}
	s.repos[workspaceRoot] = repository
	s.loggers[workspaceRoot] = logger
	s.policies[workspaceRoot] = retention
	return repository, nil
}

func (s *runControlState) Close() {
	if s == nil {
		return
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	for root, repository := range s.repos {
		_ = repository.Close()
		if logger := s.loggers[root]; logger != nil {
			_ = logger.Close()
			delete(s.loggers, root)
		}
		delete(s.repos, root)
	}
}

func currentRunOwner() (runcontrol.Owner, error) {
	return runcontrol.NewProcessOwner()
}

type controlledRuntime struct {
	base interface {
		StartRun(context.Context, runtimepkg.Request) (runtimepkg.Result, error)
	}
	repository runcontrol.Repository
	owner      runcontrol.Owner
}

func (r controlledRuntime) DeleteSession(ctx context.Context, sessionID string) error {
	deleter, ok := r.base.(interface {
		DeleteSession(context.Context, string) error
	})
	if !ok {
		return nil
	}
	return deleter.DeleteSession(ctx, sessionID)
}

func (r controlledRuntime) DeleteSessions(ctx context.Context, sessionIDs []string) error {
	deleter, ok := r.base.(interface {
		DeleteSessions(context.Context, []string) error
	})
	if !ok {
		for _, sessionID := range sessionIDs {
			if err := r.DeleteSession(ctx, sessionID); err != nil {
				return err
			}
		}
		return nil
	}
	return deleter.DeleteSessions(ctx, sessionIDs)
}

func (r controlledRuntime) DeleteRuntimeStore(ctx context.Context, path string) error {
	deleter, ok := r.base.(interface {
		DeleteRuntimeStore(context.Context, string) error
	})
	if !ok {
		return nil
	}
	return deleter.DeleteRuntimeStore(ctx, path)
}

func controlledRuntimeFor(deps dependencies, workspaceRoot string, effectiveConfig config.Config, base interface {
	StartRun(context.Context, runtimepkg.Request) (runtimepkg.Result, error)
}) (controlledRuntime, error) {
	if deps.runControl == nil {
		return controlledRuntime{}, errors.New("run-control process state is unavailable")
	}
	repository, err := deps.runControl.repository(deps.ctx, workspaceRoot, runControlRetentionPolicy(effectiveConfig))
	if err != nil {
		return controlledRuntime{}, fmt.Errorf("open durable run control: %w", err)
	}
	return controlledRuntime{base: base, repository: repository, owner: deps.runControl.owner}, nil
}

func runControlRetentionPolicy(c config.Config) runcontrol.RetentionPolicy {
	full, _ := time.ParseDuration(c.RunControl.FullHistory)
	tombstone, _ := time.ParseDuration(c.RunControl.TombstoneHistory)
	return runcontrol.RetentionPolicy{FullHistory: full, TombstoneHistory: tombstone, HardQuotaBytes: c.RunControl.WorkspaceQuota}
}

func (r controlledRuntime) StartRun(ctx context.Context, req runtimepkg.Request) (runtimepkg.Result, error) {
	target := targetFromRuntimeRequest(req)
	correlation := runcontrol.Correlation{
		ProductRunID:  boundedSafe(string(runcontrol.ParentRun(ctx))),
		ProductTaskID: boundedSafe(req.TraceID),
	}
	snapshot, err := r.repository.Accept(ctx, runcontrol.Acceptance{
		Target:        target,
		Correlation:   correlation,
		ProductStatus: "accepted",
	})
	if err != nil {
		return runtimepkg.Result{}, fmt.Errorf("durable run acceptance failed: %w", err)
	}
	attempt, _, err := r.repository.Claim(ctx, runcontrol.Claim{
		RunID: snapshot.RunID, Owner: r.owner, Lease: runControlLease, Correlation: correlation,
	})
	if err != nil {
		return runtimepkg.Result{}, fmt.Errorf("durable run ownership failed: %w", err)
	}
	fence := runcontrol.Fence{
		RunID: snapshot.RunID, AttemptID: attempt.ID, OwnerID: r.owner.ID,
		FencingGeneration: attempt.FencingGeneration,
	}

	runCtx, cancel := context.WithCancel(ctx)
	defer cancel()
	req.Metadata = cloneRuntimeMetadata(req.Metadata)
	req.Metadata["run_control_run_id"] = string(snapshot.RunID)
	configuredOnEvent := req.OnEvent
	var eventMu sync.Mutex
	var persistenceErr error
	var progressKey string
	var progressCommittedAt time.Time
	var progressOmitted uint64
	var progressOmittedFirst time.Time
	var progressOmittedLast time.Time
	setPersistenceErr := func(value error) {
		eventMu.Lock()
		defer eventMu.Unlock()
		if persistenceErr == nil {
			persistenceErr = value
			cancel()
		}
	}
	req.OnEvent = func(event runtimepkg.Event) {
		eventMu.Lock()
		defer eventMu.Unlock()
		if persistenceErr != nil {
			return
		}
		draft := runtimeEventDraft(req, event)
		eventAt := event.Time.UTC()
		if eventAt.IsZero() {
			eventAt = time.Now().UTC()
		}
		// Content-aware coalescing: only collapse identical progress payloads within the window.
		// Reasoning/text deltas and tool calls have distinct payload hashes and will not coalesce.
		hash := payloadHash(draft.Payload)
		key := string(draft.Type) + "\x00" + draft.Stage + "\x00" + draft.Task + "\x00" + hash
		elapsed := eventAt.Sub(progressCommittedAt)
		if draft.Type == runcontrol.EventProgress && key == progressKey && elapsed >= 0 && elapsed < runcontrol.ProgressCoalesceWindow {
			if progressOmitted == 0 {
				progressOmittedFirst = eventAt
			}
			progressOmitted++
			progressOmittedLast = eventAt
			return
		}
		if progressOmitted > 0 {
			if draft.Omission == nil {
				draft.Omission = &runcontrol.Omission{Reason: "equivalent progress coalesced"}
			}
			draft.Omission.Count += progressOmitted
			draft.Omission.FirstAt = &progressOmittedFirst
			draft.Omission.LastAt = &progressOmittedLast
			progressOmitted = 0
		}
		if _, _, appendErr := appendRunEventWithRetry(runCtx, r.repository, fence, draft); appendErr != nil {
			persistenceErr = fmt.Errorf("persist runtime event: %w", appendErr)
			cancel()
			return
		}
		if draft.Type == runcontrol.EventProgress {
			progressKey = key
			progressCommittedAt = eventAt
		}
		if configuredOnEvent != nil {
			configuredOnEvent(event)
		}
	}

	controlDone := make(chan struct{})
	go func() {
		defer close(controlDone)
		ticker := time.NewTicker(runcontrol.OwnerTickInterval)
		defer ticker.Stop()
		lastHeartbeat := time.Now()
		lastReconcile := time.Now()
		for {
			select {
			case <-runCtx.Done():
				return
			case now := <-ticker.C:
				snapshot, err := r.repository.Snapshot(runCtx, fence.RunID)
				if err != nil {
					if runCtx.Err() != nil {
						return
					}
					setPersistenceErr(fmt.Errorf("poll durable run control: %w", err))
					return
				}
				if snapshot.Cancellation.State == runcontrol.CancellationRequested {
					if _, _, err := r.repository.AcknowledgeCancellation(runCtx, fence); err != nil {
						setPersistenceErr(fmt.Errorf("acknowledge durable cancellation: %w", err))
						return
					}
					cancel()
					return
				}
				if now.Sub(lastHeartbeat) >= runcontrol.HeartbeatInterval {
					if _, err := r.repository.Heartbeat(runCtx, fence, runControlLease); err != nil {
						if runCtx.Err() != nil {
							return
						}
						setPersistenceErr(fmt.Errorf("persist owner heartbeat: %w", err))
						return
					}
					lastHeartbeat = now
				}
				if now.Sub(lastReconcile) >= runcontrol.ReconciliationInterval {
					if _, err := r.repository.Reconcile(runCtx, runcontrol.NativeProcessProbe{}, runcontrol.ReconcileOptions{}); err != nil {
						if runCtx.Err() != nil {
							return
						}
						setPersistenceErr(fmt.Errorf("reconcile durable runs: %w", err))
						return
					}
					lastReconcile = now
				}
			}
		}
	}()
	result, runErr := r.base.StartRun(runCtx, req)
	eventMu.Lock()
	if persistenceErr == nil && progressOmitted > 0 {
		_, _, appendErr := appendRunEventWithRetry(runCtx, r.repository, fence, runcontrol.EventDraft{
			Type: runcontrol.EventOmission,
			Omission: &runcontrol.Omission{
				Reason: "equivalent progress coalesced", Count: progressOmitted,
				FirstAt: &progressOmittedFirst, LastAt: &progressOmittedLast,
			},
		})
		if appendErr != nil {
			persistenceErr = fmt.Errorf("persist progress omission: %w", appendErr)
		}
	}
	eventMu.Unlock()
	cancel()
	<-controlDone
	eventMu.Lock()
	persistErr := persistenceErr
	eventMu.Unlock()
	if persistErr != nil {
		terminalCtx, terminalCancel := context.WithTimeout(context.Background(), 30*time.Second)
		_, _, terminalErr := proposeRunTerminalWithRetry(terminalCtx, r.repository, fence, runcontrol.TerminalProposal{
			Outcome: runcontrol.TerminalPersistenceLost, Reason: "durable event persistence failed", ProposedBy: r.owner.ID,
		})
		terminalCancel()
		if terminalErr != nil {
			return result, errors.Join(persistErr, terminalErr)
		}
		return result, persistErr
	}

	outcome, reason := terminalOutcome(result, runErr, ctx)
	terminalCtx, terminalCancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer terminalCancel()
	if _, _, err := proposeRunTerminalWithRetry(terminalCtx, r.repository, fence, runcontrol.TerminalProposal{
		Outcome: outcome, Reason: reason, ProposedBy: r.owner.ID,
	}); err != nil {
		return result, errors.Join(runErr, fmt.Errorf("persist terminal run outcome: %w", err))
	}
	return result, runErr
}

func appendRunEventWithRetry(ctx context.Context, repository runcontrol.Repository, fence runcontrol.Fence, draft runcontrol.EventDraft) (runcontrol.Event, runcontrol.Snapshot, error) {
	deadline := time.Now().Add(5 * time.Second)
	for {
		event, snapshot, err := repository.Append(ctx, fence, draft)
		if err == nil || !retryableRunControlError(err) || !time.Now().Before(deadline) {
			return event, snapshot, err
		}
		if err := waitRunControlRetry(ctx, deadline); err != nil {
			return runcontrol.Event{}, runcontrol.Snapshot{}, err
		}
	}
}

func proposeRunTerminalWithRetry(ctx context.Context, repository runcontrol.Repository, fence runcontrol.Fence, proposal runcontrol.TerminalProposal) (runcontrol.Snapshot, bool, error) {
	for {
		snapshot, won, err := repository.ProposeTerminal(ctx, fence, proposal)
		if err == nil || !retryableRunControlError(err) {
			return snapshot, won, err
		}
		if err := waitRunControlRetry(ctx, time.Now().Add(250*time.Millisecond)); err != nil {
			return runcontrol.Snapshot{}, false, err
		}
	}
}

func retryableRunControlError(err error) bool {
	return errors.Is(err, runcontrol.ErrUnavailable) || errors.Is(err, runcontrol.ErrBusy)
}

func waitRunControlRetry(ctx context.Context, deadline time.Time) error {
	wait := time.Until(deadline)
	if wait > 100*time.Millisecond {
		wait = 100 * time.Millisecond
	}
	if wait <= 0 {
		return context.DeadlineExceeded
	}
	timer := time.NewTimer(wait)
	defer timer.Stop()
	select {
	case <-ctx.Done():
		return ctx.Err()
	case <-timer.C:
		return nil
	}
}

func targetFromRuntimeRequest(req runtimepkg.Request) runcontrol.Target {
	target := runcontrol.Target{
		Kind:      boundedSafe(req.PromptRef.OwnerKind),
		Operation: boundedSafe(req.PromptRef.Purpose),
		Project:   boundedSafe(req.Metadata["project"]),
		Sprint:    boundedSafe(req.Metadata["sprint"]),
		Study:     boundedSafe(req.Metadata["study"]),
		Stage:     boundedSafe(req.Metadata["stage"]),
		Task:      boundedSafe(firstSafeValue(req.Metadata["task"], req.Metadata["task.kind"], req.Metadata["coverage"])),
	}
	if target.Kind == "" {
		if target.Study != "" {
			target.Kind = "study"
		} else if target.Sprint != "" {
			target.Kind = "sprint"
		} else {
			target.Kind = "runtime"
		}
	}
	if target.Operation == "" {
		target.Operation = boundedSafe(firstSafeValue(target.Stage, req.Metadata["task.kind"], req.PromptRef.ID, "runtime"))
	}
	return target
}

func runtimeEventDraft(req runtimepkg.Request, event runtimepkg.Event) runcontrol.EventDraft {
	eventType := runcontrol.EventProgress
	lowerType := strings.ToLower(strings.TrimSpace(event.Type))
	lowerKind := strings.ToLower(strings.TrimSpace(event.Kind))
	switch lowerType {
	case "warning", "warn", "error":
		eventType = runcontrol.EventWarning
	case "artifact", "file":
		eventType = runcontrol.EventArtifact
	case "finding":
		eventType = runcontrol.EventFinding
	case "message", "text", "output", "assistant_text", "reasoning_text", "reasoning", "content", "delta":
		eventType = runcontrol.EventMessage
	default:
		// Kind-based fallback: reasoning and message kinds should be visible as message, not coalesced progress.
		switch lowerKind {
		case "message", "reasoning", "assistant", "assistant_text", "reasoning_text":
			eventType = runcontrol.EventMessage
		case "tool", "tool_use", "tool_call", "tool_call_update":
			// Tools stay as progress but with distinct payload so coalescing can distinguish.
			eventType = runcontrol.EventProgress
		}
	}
	payload := map[string]string{
		"runtime_event_id": boundedSafe(event.ID),
		"runtime_run_id":   boundedSafe(event.RunID),
		"session_id":       boundedSafe(event.SessionID),
		"type":             boundedSafe(event.Type),
		"kind":             boundedSafe(event.Kind),
	}
	if lowerKind == "tool" || lowerKind == "tool_use" || lowerKind == "tool_call" || lowerKind == "tool_call_update" {
		captureToolObservation(payload, event.Payload)
	}
	// Preserve safe observable payload fields into durable storage for observability.
	// Deny sensitive keys and truncate values to runcontrol-safe limits.
	// Flatten one level of nesting so tool/action names buried in maps are surfaced as top-level payload keys
	// that the run timeline JS expects (payload.tool, payload.action, payload.title, etc.).
	for key, value := range event.Payload {
		if isSensitivePayloadKey(key) {
			continue
		}
		normalized := strings.TrimSpace(key)
		if normalized == "" || len(normalized) > 128 || strings.ContainsAny(normalized, "\x00\r\n") {
			continue
		}
		if normalized == "type" || normalized == "kind" {
			continue
		}
		if nested, ok := value.(map[string]any); ok {
			for subKey, subVal := range nested {
				if isSensitivePayloadKey(subKey) {
					continue
				}
				subNorm := strings.TrimSpace(subKey)
				if subNorm == "" || len(subNorm) > 128 || strings.ContainsAny(subNorm, "\x00\r\n") {
					continue
				}
				if _, exists := payload[subNorm]; exists {
					continue
				}
				// Promote common observable sub-keys; namespace the rest to avoid collisions.
				promote := map[string]bool{"tool": true, "title": true, "detail": true, "text": true, "delta": true, "content": true, "message": true, "action": true, "state": true, "status": true, "native_type": true, "line": true}
				targetKey := subNorm
				if !promote[subNorm] {
					targetKey = normalized + "_" + subNorm
					if len(targetKey) > 128 {
						continue
					}
				}
				if _, exists := payload[targetKey]; exists {
					continue
				}
				str := payloadValueString(subVal)
				if strings.TrimSpace(str) == "" {
					continue
				}
				if len(payload) >= 30 {
					break
				}
				payload[targetKey] = boundedPayloadValue(str)
			}
			// Also keep a compact stringified top-level for debugging if not promoted.
			if len(payload) < 30 {
				if _, exists := payload[normalized]; !exists {
					str := payloadValueString(value)
					if strings.TrimSpace(str) != "" && !strings.HasPrefix(str, "[map omitted") {
						payload[normalized] = boundedPayloadValue(str)
					}
				}
			}
			continue
		}
		str := payloadValueString(value)
		if strings.TrimSpace(str) == "" {
			continue
		}
		if len(payload) >= 30 {
			break
		}
		if _, exists := payload[normalized]; exists {
			continue
		}
		payload[normalized] = boundedPayloadValue(str)
	}
	// Ensure the most useful display keys are always present even if nested.
	for _, want := range []string{"tool", "action", "title", "detail", "text", "delta"} {
		if _, ok := payload[want]; ok {
			continue
		}
		if v := findNestedString(event.Payload, want); v != "" {
			payload[want] = boundedPayloadValue(v)
		}
	}
	omission := (*runcontrol.Omission)(nil)
	if event.RawPresent || event.RawOmitted {
		reason := firstSafeValue(event.RawOmissionReason, "runtime payload omitted by safe persistence policy")
		omission = &runcontrol.Omission{Reason: boundedSafe(reason), Count: 1}
	} else if len(event.Payload) > len(payload)-5 {
		// Payload had more fields than we persisted (truncated/omitted keys) – record for diagnostics but don't hide persisted fields.
		omission = &runcontrol.Omission{Reason: boundedSafe("runtime payload truncated to safe observable fields"), Count: 1}
	}
	return runcontrol.EventDraft{
		Type: eventType, Scope: runcontrol.EventScopeRuntime,
		Stage: boundedSafe(req.Metadata["stage"]), Task: boundedSafe(firstSafeValue(req.Metadata["task"], req.Metadata["task.kind"])),
		Kind: payload["kind"], Tool: payload["tool"], Action: payload["action"],
		Reason: payload["reason"], Detail: firstSafeValue(payload["detail"], payload["title"]),
		Payload: payload, Omission: omission,
	}
}

func isSensitivePayloadKey(key string) bool {
	lower := strings.ToLower(key)
	for _, marker := range []string{"secret", "token", "password", "authorization", "cookie", "api_key", "apikey", "credential", "auth"} {
		if strings.Contains(lower, marker) {
			return true
		}
	}
	return false
}

func findNestedString(payload map[string]any, want string) string {
	for _, v := range payload {
		if m, ok := v.(map[string]any); ok {
			if s, ok := m[want].(string); ok && strings.TrimSpace(s) != "" {
				return s
			}
			// One more level deep (common for opencode part.state structures)
			for _, inner := range m {
				if innerMap, ok := inner.(map[string]any); ok {
					if s, ok := innerMap[want].(string); ok && strings.TrimSpace(s) != "" {
						return s
					}
				}
			}
		}
	}
	return ""
}

func payloadValueString(value any) string {
	switch v := value.(type) {
	case string:
		return v
	case []byte:
		if len(v) == 0 {
			return ""
		}
		return string(v)
	case bool:
		if v {
			return "true"
		}
		return "false"
	case int:
		return fmt.Sprintf("%d", v)
	case int8:
		return fmt.Sprintf("%d", v)
	case int16:
		return fmt.Sprintf("%d", v)
	case int32:
		return fmt.Sprintf("%d", v)
	case int64:
		return fmt.Sprintf("%d", v)
	case uint, uint8, uint16, uint32, uint64:
		return fmt.Sprintf("%d", v)
	case float32, float64:
		return fmt.Sprintf("%v", v)
	case map[string]any, map[string]string, []any, []string:
		// Encode structured values compactly.
		encoded, err := jsonMarshalTruncated(v)
		if err != nil {
			return fmt.Sprintf("%v", v)
		}
		return encoded
	default:
		return fmt.Sprintf("%v", v)
	}
}

func jsonMarshalTruncated(v any) (string, error) {
	encoded, err := json.Marshal(v)
	if err != nil {
		return "", err
	}
	return string(encoded), nil
}

func captureToolObservation(out map[string]string, payload map[string]any) {
	for target, aliases := range map[string][]string{
		"tool_call_id": {"tool_call_id", "toolCallId", "call_id", "callID"},
		"tool_name":    {"tool_name", "toolName", "tool", "name"},
		"tool_status":  {"tool_status", "status", "phase"},
	} {
		if value := findNestedPayloadValue(payload, aliases, 0); value != nil {
			if text, ok := value.(string); ok && strings.TrimSpace(text) != "" {
				out[target] = boundedPayloadValue(text)
			}
		}
	}
	for target, aliases := range map[string][]string{
		"tool_arguments": {"tool_arguments", "arguments", "args", "input", "parameters"},
		"tool_result":    {"tool_result", "result", "output", "content"},
		"tool_error":     {"tool_error", "error"},
	} {
		value := findNestedPayloadValue(payload, aliases, 0)
		if value == nil {
			continue
		}
		encoded, err := json.Marshal(redactObservableValue(value))
		if err == nil && string(encoded) != "null" {
			out[target] = boundedPayloadValue(string(encoded))
		}
	}
	if out["tool"] == "" {
		out["tool"] = out["tool_name"]
	}
}

func findNestedPayloadValue(value any, aliases []string, depth int) any {
	if depth > 5 {
		return nil
	}
	switch typed := value.(type) {
	case map[string]any:
		for _, key := range aliases {
			if found, ok := typed[key]; ok && found != nil {
				return found
			}
		}
		keys := make([]string, 0, len(typed))
		for key := range typed {
			keys = append(keys, key)
		}
		sort.Strings(keys)
		for _, key := range keys {
			if found := findNestedPayloadValue(typed[key], aliases, depth+1); found != nil {
				return found
			}
		}
	case []any:
		for _, item := range typed {
			if found := findNestedPayloadValue(item, aliases, depth+1); found != nil {
				return found
			}
		}
	}
	return nil
}

func redactObservableValue(value any) any {
	switch typed := value.(type) {
	case map[string]any:
		redacted := make(map[string]any, len(typed))
		for key, item := range typed {
			if isSensitivePayloadKey(key) {
				redacted[key] = "[REDACTED]"
			} else {
				redacted[key] = redactObservableValue(item)
			}
		}
		return redacted
	case []any:
		redacted := make([]any, len(typed))
		for index, item := range typed {
			redacted[index] = redactObservableValue(item)
		}
		return redacted
	case string:
		lower := strings.ToLower(typed)
		for _, marker := range []string{"bearer ", "sk-", "ghp_", "github_pat_", "-----begin private key"} {
			if strings.Contains(lower, marker) {
				return "[REDACTED]"
			}
		}
		return typed
	default:
		return value
	}
}

func boundedPayloadValue(value string) string {
	value = strings.Map(func(r rune) rune {
		if r == 0 || r == '\r' || r == '\n' {
			return -1
		}
		return r
	}, strings.TrimSpace(value))
	if len(value) > runcontrol.MaxSafeValueBytes {
		value = value[:runcontrol.MaxSafeValueBytes]
	}
	return value
}

func payloadHash(payload map[string]string) string {
	if len(payload) == 0 {
		return ""
	}
	// Stable hash of payload content for coalescing: include type/kind and any payload_* keys.
	keys := make([]string, 0, len(payload))
	for k := range payload {
		if k == "runtime_event_id" || k == "runtime_run_id" || k == "session_id" {
			continue
		}
		keys = append(keys, k)
	}
	// Keep deterministic order by sorting.
	sortStrings(keys)
	var b strings.Builder
	for _, k := range keys {
		b.WriteString(k)
		b.WriteString("=")
		b.WriteString(payload[k])
		b.WriteString("\x00")
	}
	return b.String()
}

func sortStrings(values []string) {
	// Insertion sort for small slices – avoid importing sort for minimal diff; keep stdlib sort if available.
	for i := 1; i < len(values); i++ {
		j := i
		for j > 0 && values[j-1] > values[j] {
			values[j-1], values[j] = values[j], values[j-1]
			j--
		}
	}
}

func terminalOutcome(result runtimepkg.Result, runErr error, parent context.Context) (runcontrol.TerminalOutcome, string) {
	status := strings.ToLower(strings.TrimSpace(result.Status))
	switch {
	case errors.Is(runErr, context.DeadlineExceeded), errors.Is(parent.Err(), context.DeadlineExceeded), result.Error != nil && result.Error.Category == "timeout":
		return runcontrol.TerminalTimedOut, "runtime deadline exceeded"
	case errors.Is(runErr, context.Canceled), errors.Is(parent.Err(), context.Canceled), status == "cancelled", result.Error != nil && result.Error.Category == "cancellation":
		return runcontrol.TerminalCancelled, "runtime cancelled"
	case runErr != nil, status == "failed", status == "error":
		return runcontrol.TerminalFailed, "runtime failed"
	default:
		return runcontrol.TerminalSucceeded, "runtime completed"
	}
}

func cloneRuntimeMetadata(input map[string]string) map[string]string {
	out := make(map[string]string, len(input)+1)
	for key, value := range input {
		out[key] = value
	}
	return out
}

func boundedSafe(value string) string {
	value = strings.Map(func(r rune) rune {
		if r == 0 || r == '\r' || r == '\n' {
			return -1
		}
		return r
	}, strings.TrimSpace(value))
	if len(value) > runcontrol.MaxTargetFieldBytes {
		value = value[:runcontrol.MaxTargetFieldBytes]
	}
	return value
}

func firstSafeValue(values ...string) string {
	for _, value := range values {
		if strings.TrimSpace(value) != "" {
			return value
		}
	}
	return ""
}

package app

import (
	"context"
	"fmt"
	"strings"
	"time"

	"github.com/Antonio7098/ultraplan-go/internal/platform/config"
	"github.com/Antonio7098/ultraplan-go/internal/sprint"
	"github.com/Antonio7098/ultraplan-go/internal/study"
	"github.com/Antonio7098/ultraplan-go/internal/workspace"
)

// sharedOperationRunner is the single runtime-backed implementation used by
// terminal and browser adapters. Surface code owns presentation and
// confirmation; workflow semantics remain here and in the product services.
func sharedOperationRunner(deps dependencies, root workspace.Root, effective config.Effective, useCases dashboardUseCases) func(context.Context, OperationRequest, func(OperationEvent)) (OperationResult, error) {
	return func(ctx context.Context, req OperationRequest, emit func(OperationEvent)) (OperationResult, error) {
		result := OperationResult{State: OperationComplete, Subject: operationFirstNonEmpty(req.Project+"/"+req.Sprint, req.Study)}
		switch req.Kind {
		case OperationStage:
			service, e := sprintRuntimeService(deps, root, tuiSprintRuntimeProgress(emit))
			if e != nil {
				return failedOperation(result, e)
			}
			r, e := service.FlowStage(ctx, req.Project, req.Sprint, stageFlowRequest(req, func(progress sprint.FlowProgress) {
				summary := displaySafe(progress.Message)
				emit(OperationEvent{State: OperationRunning, Stage: string(progress.Stage), Message: progress.State + ": " + summary, PhaseState: progress.State, SafeSummary: summary})
			}))
			result.Message = r.Message
			result = operationWithSprintFindings(result, r.Findings)
			if e != nil {
				return failedOperation(result, e)
			}
		case OperationFlow:
			service, e := sprintRuntimeService(deps, root, tuiSprintRuntimeProgress(emit))
			if e != nil {
				return failedOperation(result, e)
			}
			flow := stageFlowRequest(req, func(progress sprint.FlowProgress) {
				summary := displaySafe(progress.Message)
				emit(OperationEvent{State: OperationRunning, Stage: string(progress.Stage), Message: progress.State + ": " + summary, PhaseState: progress.State, SafeSummary: summary})
			})
			flow.Review = sprint.ReviewRequest{Restart: req.RestartReview}
			flow.Smoke = sprint.SmokeRequest{NonInteractive: true, OverrideConfirmed: req.ForceReview, ForceReview: req.ForceReview, OverrideRationale: req.OverrideRationale}
			r, e := runSprintFlow(ctx, service, req.Project, req.Sprint, flow)
			result.Message = r.Message
			result = operationWithSprintFindings(result, r.Findings)
			if e != nil {
				return failedOperation(result, e)
			}
		case OperationExecuteStart, OperationExecuteResume:
			service, e := sprintRuntimeService(deps, root, tuiSprintRuntimeProgress(emit))
			if e != nil {
				return failedOperation(result, e)
			}
			r, e := service.Execute(ctx, req.Project, req.Sprint, sprint.ExecuteRequest{TaskID: req.Task, ModelOverride: req.Model, Resume: req.Kind == OperationExecuteResume})
			result.Message = r.Message
			result = operationWithSprintFindings(result, r.Findings)
			if e != nil {
				return failedOperation(result, e)
			}
		case OperationReviewStart:
			service, e := sprintRuntimeService(deps, root, tuiSprintRuntimeProgress(emit))
			if e != nil {
				return failedOperation(result, e)
			}
			r, e := service.Review(ctx, req.Project, req.Sprint, sprint.ReviewRequest{Concurrency: req.Parallelism, Focus: req.ReviewFocus, Restart: req.RestartReview, ModelOverride: req.Model, Progress: func(p sprint.ReviewProgress) {
				emit(OperationEvent{State: OperationRunning, Stage: "review", Task: p.CoverageID, Message: p.Message, Completed: p.Completed, Total: p.Total})
			}})
			result.Message = fmt.Sprintf("%s verdict=%s", r.Status, r.Verdict)
			for _, f := range r.Findings {
				result.Findings = append(result.Findings, DisplayFinding{Severity: f.Severity, Section: "review", Problem: f.Title, Cause: f.Detail, Suggestion: f.Action})
			}
			if e != nil {
				return failedOperation(result, e)
			}
		case OperationSmokeStart:
			service := sprint.NewService(root.Path).WithPublisher(stagePublisher(effective.Config)).WithSmokeSettings(smokeSettings(effective, envLookup(deps.env)))
			var timeout time.Duration
			if req.Timeout != "" {
				timeout, _ = time.ParseDuration(req.Timeout)
			}
			r, e := service.RunSmoke(ctx, req.Project, req.Sprint, sprint.SmokeRequest{Level: req.Level, Suite: req.Suite, Test: req.Test, Timeout: timeout, ForceReview: req.ForceReview, OverrideConfirmed: req.ForceReview, OverrideRationale: req.OverrideRationale, Progress: func(p sprint.SmokeProgress) {
				emit(OperationEvent{State: OperationRunning, Stage: string(p.Phase), Task: operationFirstNonEmpty(p.Test, p.Suite), Message: p.Message, Completed: p.Completed, Total: p.Total})
			}})
			result.Message = fmt.Sprintf("%s verdict=%s run=%s next=%s", r.Status, r.Verdict, r.RunID, r.NextAction)
			if r.Artifact != "" {
				if preview, readErr := useCases.PreviewArtifact(ctx, r.Artifact); readErr == nil {
					result.Content, result.Truncated = boundContent(preview.Content)
				}
			}
			if e != nil {
				return failedOperation(result, e)
			}
		case OperationVerifyStart:
			service, e := sprintRuntimeService(deps, root, tuiSprintRuntimeProgress(emit))
			if e != nil {
				return failedOperation(result, e)
			}
			var timeout time.Duration
			if req.Timeout != "" {
				timeout, _ = time.ParseDuration(req.Timeout)
			}
			r, e := service.Verify(ctx, req.Project, req.Sprint, sprint.VerifyRequest{To: sprint.PlanningStage(req.Stage), Review: sprint.ReviewRequest{Focus: req.ReviewFocus, Restart: req.RestartReview}, Smoke: sprint.SmokeRequest{Level: req.Level, Suite: req.Suite, Test: req.Test, Timeout: timeout, ForceReview: req.ForceReview, OverrideConfirmed: req.ForceReview, OverrideRationale: req.OverrideRationale}, Progress: func(p sprint.FlowProgress) {
				summary := displaySafe(p.Message)
				emit(OperationEvent{State: OperationRunning, Stage: string(p.Stage), Message: p.State + ": " + summary, PhaseState: p.State, SafeSummary: summary})
			}})
			result.Message = fmt.Sprintf("assessment=%s next=%s", r.Verification.Assessment, r.Verification.NextAction)
			if e != nil {
				return failedOperation(result, e)
			}
		case OperationQAStart, OperationQAResume:
			token, fence, e := qaOwnershipFromContext(ctx)
			if e != nil {
				return failedOperation(result, e)
			}
			service, e := sprintRuntimeService(deps, root, tuiSprintRuntimeProgress(emit))
			if e != nil {
				return failedOperation(result, e)
			}
			service = service.WithQAWriterFence(fence)
			r, e := service.RunQA(ctx, req.Project, req.Sprint, sprint.QARunRequest{Resume: req.Kind == OperationQAResume, FocusShard: req.Task, Suite: req.Suite, EvidenceProducing: req.Suite == "", WriterToken: token, Progress: func(progress sprint.QAProgress) {
				emit(OperationEvent{State: OperationRunning, Stage: string(progress.Phase), Task: progress.ShardID, Message: progress.Message, Action: progress.Event, Reason: string(progress.ShardPhase), Detail: string(progress.ShardKind), Completed: progress.Completed, Total: progress.Total})
			}})
			result.Message = fmt.Sprintf("phase=%s shards=%d/%d next=%s", r.State.Phase, r.State.CompletedShards, r.State.TotalShards, r.State.NextAction)
			if e != nil {
				return failedOperation(result, e)
			}
		case OperationStudyStart, OperationStudyResume:
			flags := runAllFlags{}
			flags.parallelism = &req.Parallelism
			flags.model = req.Model
			service, parallel, summary, e := runLoopService(deps, root, flags)
			if e != nil {
				return failedOperation(result, e)
			}
			r, e := service.RunLoop(ctx, study.RunLoopRequest{StudyRef: req.Study, DimensionRefs: req.Dimensions, SourceRefs: req.Sources, Parallelism: parallel, Model: studyModelOverride(deps, flags.model), Config: summary, Continue: req.Kind == OperationStudyResume, Command: []string{"ultraplan", "operation"}, Progress: func(p study.RunLoopProgress) {
				stats := operationTaskStats(p.Task, time.Now().UTC())
				event := OperationEvent{State: OperationRunning, Task: p.Task.ID, Stage: string(p.Event), Message: strings.TrimSpace(p.Task.DimensionRef + " " + p.Task.Source), Completed: p.ScopeCounts.Completed, Total: p.ScopeCounts.Total, Attempt: p.Task.Attempts, RuntimeAttempts: stats.RuntimeAttempts, Turns: stats.Turns, TurnsKnown: stats.TurnsKnown, Tokens: stats.Tokens, TokensKnown: stats.TokensKnown, InputTokens: stats.InputTokens, OutputTokens: stats.OutputTokens, ReasoningTokens: stats.ReasoningTokens, CacheReadTokens: stats.CacheReadTokens, CacheWriteTokens: stats.CacheWriteTokens, Duration: stats.Duration, Provider: stats.Provider, Model: stats.Model, Harness: stats.Runtime, Cost: stats.Cost, RuntimeEvents: stats.Events}
				if p.RuntimeEvent != nil {
					applyRuntimeObservation(&event, *p.RuntimeEvent)
					event.Message = runtimeProgressSummary(*p.RuntimeEvent)
				}
				emit(event)
			}})
			result.Message = string(r.Status)
			if e != nil {
				return failedOperation(result, e)
			}
		case OperationStudyCancel:
			service := study.NewService(root.Path)
			listing, e := service.ListStudy(req.Study)
			if e != nil {
				return failedOperation(result, e)
			}
			info, e := study.CancelRunLoop(listing.Study)
			if e != nil {
				return failedOperation(result, e)
			}
			result.Message = fmt.Sprintf("cancellation requested from run-loop process %d", info.PID)
		default:
			return failedOperation(result, fmt.Errorf("unsupported runtime operation %q", req.Kind))
		}
		emit(OperationEvent{State: OperationComplete, Message: "operation complete"})
		return result, nil
	}
}

// stageFlowRequest builds the sprint flow request for a stage or flow
// operation. A requested model applies to the selected target stage and, as a
// fallback for stages without dedicated per-stage handling (code-context), as
// the generic model override. Empty models keep configured defaults.
func stageFlowRequest(req OperationRequest, progress func(sprint.FlowProgress)) sprint.FlowRequest {
	flow := sprint.FlowRequest{To: sprint.PlanningStage(req.Stage), ModelOverride: req.Model}
	if req.Model != "" && req.Stage != "" {
		stage := sprint.PlanningStage(req.Stage)
		if _, ok := flow.StageOverrides[stage]; !ok {
			flow.StageOverrides = map[sprint.PlanningStage]sprint.StageRuntime{}
		}
		override := flow.StageOverrides[stage]
		override.Model = req.Model
		flow.StageOverrides[stage] = override
	}
	flow.Progress = progress
	return flow
}

