package app

import (
	"context"
	"errors"
	"sync/atomic"
	"testing"
	"time"

	runtimepkg "github.com/Antonio7098/ultraplan-go/internal/platform/runtime"
	"github.com/Antonio7098/ultraplan-go/internal/runcontrol"
)

// REPRO 1: controlledRuntime trailing omission flush runs on the already
// canceled runCtx, so a normal user cancellation with one pending coalesced
// progress duplicate is terminalized as persistence_degraded instead of
// cancelled, and the original cancellation error is replaced.
func TestReproFlushOnCanceledContextMisclassifiesCancelAsPersistenceLost(t *testing.T) {
	ctx := context.Background()
	repository, err := runcontrol.OpenSQLite(ctx, t.TempDir(), runcontrol.SQLiteOptions{})
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = repository.Close() })
	owner, err := currentRunOwner()
	if err != nil {
		t.Fatal(err)
	}
	parent, cancelParent := context.WithCancel(ctx)
	spy := &flushSpy{parent: parent, cancelParent: cancelParent}
	controlled := controlledRuntime{base: spy, repository: repository, owner: owner}
	result, runErr := controlled.StartRun(parent, runtimepkg.Request{
		PromptRef: runtimepkg.PromptReference{OwnerKind: "sprint", Purpose: "execute"},
		Metadata:  map[string]string{"project": "alpha", "sprint": "1", "stage": "execute"},
	})
	t.Logf("StartRun returned result=%+v err=%v (errors.Is Canceled=%v)", result, runErr, errors.Is(runErr, context.Canceled))
	runID := runcontrol.RunID(spy.request.Metadata["run_control_run_id"])
	snapshot, err := repository.Snapshot(ctx, runID)
	if err != nil {
		t.Fatal(err)
	}
	t.Logf("durable terminal outcome=%q reason=%q", snapshot.Terminal.Outcome, snapshot.Terminal.Reason)
	if snapshot.Terminal.Outcome != runcontrol.TerminalCancelled {
		t.Fatalf("MISCLASSIFIED: user cancellation recorded as %q (want cancelled); reason=%q", snapshot.Terminal.Outcome, snapshot.Terminal.Reason)
	}
}

type flushSpy struct {
	parent       context.Context
	cancelParent context.CancelFunc
	request      runtimepkg.Request
}

func (s *flushSpy) StartRun(ctx context.Context, request runtimepkg.Request) (runtimepkg.Result, error) {
	s.request = request
	emit := request.OnEvent
	emit(runtimepkg.Event{ID: "e1", Type: "progress", Payload: map[string]any{"state": "running"}})
	emit(runtimepkg.Event{ID: "e2", Type: "progress", Payload: map[string]any{"state": "running"}})
	<-ctx.Done()
	return runtimepkg.Result{}, ctx.Err()
}

// REPRO 2: a single manager-tier control tick failure (snapshot poll) silently
// cancels the operation; the durable record then reads as a plain user
// cancellation with no diagnostic event of any kind.
func TestReproManagerTickFailureSilentlyBecomesUserCancellation(t *testing.T) {
	ctx := context.Background()
	base, err := runcontrol.OpenSQLite(ctx, t.TempDir(), runcontrol.SQLiteOptions{})
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = base.Close() })
	repository := &flakySnapshotRepo{Repository: base}
	owner, err := currentRunOwner()
	if err != nil {
		t.Fatal(err)
	}
	manager := newDurableOperationManager(repository, owner)
	accepted, err := manager.AcceptOperation(ctx, Confirmation{Request: OperationRequest{Kind: OperationExecuteStart, Project: "alpha", Sprint: "1"}}, "")
	if err != nil {
		t.Fatal(err)
	}
	workDone := make(chan error, 1)
	go func() {
		<-accepted.Context.Done()
		workDone <- accepted.Context.Err()
	}()
	time.Sleep(1500 * time.Millisecond) // let at least one owner tick observe the failing Snapshot
	runErr := <-workDone
	finishErr := manager.FinishOperation(context.Background(), accepted.RunID, OperationComplete, runErr)
	if finishErr != nil {
		t.Fatalf("finish: %v", finishErr)
	}
	snapshot, err := repository.Snapshot(ctx, runcontrol.RunID(accepted.RunID))
	if err != nil {
		t.Fatal(err)
	}
	events, err := repository.Events(ctx, runcontrol.RunID(accepted.RunID), 0, 50)
	if err != nil {
		t.Fatal(err)
	}
	kinds := []string{}
	for _, e := range events {
		kinds = append(kinds, string(e.Type))
	}
	t.Logf("runErr=%v terminal=%q reason=%q events=%v", runErr, snapshot.Terminal.Outcome, snapshot.Terminal.Reason, kinds)
	for _, e := range events {
		if e.Type == runcontrol.EventWarning || e.Type == runcontrol.EventOmission {
			t.Fatalf("expected no diagnostic event, found %s", e.Type)
		}
	}
	if snapshot.Terminal.Outcome != runcontrol.TerminalCancelled {
		t.Fatalf("expected silent cancel misclassification, got %q", snapshot.Terminal.Outcome)
	}
}

type flakySnapshotRepo struct {
	runcontrol.Repository
	failNext atomic.Bool
}

func (r *flakySnapshotRepo) Snapshot(ctx context.Context, runID runcontrol.RunID) (runcontrol.Snapshot, error) {
	if r.failNext.CompareAndSwap(false, true) {
		return runcontrol.Snapshot{}, errors.New("injected storage outage")
	}
	return r.Repository.Snapshot(ctx, runID)
}

