type cancelSpy struct {
	request runtimepkg.Request
}

func (s *cancelSpy) StartRun(ctx context.Context, request runtimepkg.Request) (runtimepkg.Result, error) {
	s.request = request
	emit := request.OnEvent
	emit(runtimepkg.Event{ID: "e1", Type: "progress", Payload: map[string]any{"state": "running"}})
	if request.Metadata["duplicate"] == "1" {
		emit(runtimepkg.Event{ID: "e2", Type: "progress", Payload: map[string]any{"state": "running"}})
	}
	<-ctx.Done()
	return runtimepkg.Result{Status: "completed"}, ctx.Err()
}

func verifyControlledRun(t *testing.T, duplicate bool) (runcontrol.TerminalOutcome, string, error) {
	t.Helper()
	ctx := context.Background()
	repository, err := runcontrol.OpenSQLite(ctx, t.TempDir(), runcontrol.SQLiteOptions{})
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = repository.Close() })
	owner, err := currentRunOwner()
	if err != nil {
		t.Fatal(err)
	}
	parent, cancel := context.WithCancel(ctx)
	spy := &cancelSpy{}
	metadata := map[string]string{"project": "alpha", "sprint": "1", "stage": "execute"}
	if duplicate {
		metadata["duplicate"] = "1"
	}
	controlled := controlledRuntime{base: spy, repository: repository, owner: owner}
	go func() {
		time.Sleep(300 * time.Millisecond)
		cancel()
	}()
	_, runErr := controlled.StartRun(parent, runtimepkg.Request{
		PromptRef: runtimepkg.PromptReference{OwnerKind: "sprint", Purpose: "execute"},
		Metadata:  metadata,
	})
	runID := runcontrol.RunID(spy.request.Metadata["run_control_run_id"])
	snapshot, err := repository.Snapshot(ctx, runID)
	if err != nil {
		t.Fatal(err)
	}
	return snapshot.Terminal.Outcome, snapshot.Terminal.Reason, runErr
}

func TestVerifyCancelWithPendingCoalescedProgress(t *testing.T) {
	outcome, reason, runErr := verifyControlledRun(t, true)
	t.Logf("with duplicate: outcome=%q reason=%q err=%v", outcome, reason, runErr)
	if outcome != runcontrol.TerminalCancelled {
		t.Fatalf("DEFECT: user cancellation recorded as %q (reason=%q), want cancelled", outcome, reason)
	}
	if !errors.Is(runErr, context.Canceled) || strings.Contains(runErr.Error(), "persist progress omission") {
		t.Fatalf("cancellation error truth corrupted: %v", runErr)
	}
}

func TestVerifyCancelWithoutPendingCoalescedProgress(t *testing.T) {
	outcome, reason, _ := verifyControlledRun(t, false)
	t.Logf("without duplicate: outcome=%q reason=%q", outcome, reason)
	if outcome != runcontrol.TerminalCancelled {
		t.Fatalf("baseline broken: cancellation recorded as %q (reason=%q)", outcome, reason)
	}
}

