		t.Fatal(err)
	}
	manager := newDurableOperationManager(repository, owner)
	accepted, err := manager.AcceptOperation(ctx, Confirmation{Request: OperationRequest{Kind: OperationExecuteStart, Project: "alpha", Sprint: "1"}}, "")
	if err != nil {
		t.Fatal(err)
	}
	<-accepted.Context.Done()
	runErr := accepted.Context.Err()
	finishCtx, cancelFinish := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancelFinish()
	if err := manager.FinishOperation(finishCtx, accepted.RunID, OperationComplete, runErr); err != nil {
		t.Fatalf("finish: %v", err)
	}
	snapshot, err := base.Snapshot(ctx, runcontrol.RunID(accepted.RunID))
	if err != nil {
		t.Fatal(err)
	}
	events, err := base.Events(ctx, runcontrol.RunID(accepted.RunID), 0, 50)
	if err != nil {
		t.Fatal(err)
	}
	kinds := []string{}
	for _, e := range events {
		kinds = append(kinds, string(e.Type))
	}
	t.Logf("tick-failure: terminal=%q reason=%q events=%v", snapshot.Terminal.Outcome, snapshot.Terminal.Reason, kinds)
	for _, e := range events {
		if e.Type == runcontrol.EventWarning || e.Type == runcontrol.EventOmission {
			t.Logf("DIAGNOSTIC PRESENT: %s", e.Type)
			return
		}
	}
	t.Logf("DEFECT CONFIRMED SHAPE: infrastructure outage recorded identically to user cancellation (outcome=%q), zero diagnostic events", snapshot.Terminal.Outcome)
}
